def sessions(events, gap):
    """events: (key, time) pairs in any order. A session is a maximal run of one key's events in
    which each event follows the previous one by at most `gap`. Return the sorted list of
    (key, start, end, count) tuples, one per session."""
    by_key = {}
    for key, t in events:
        by_key.setdefault(key, []).append(t)
    return sorted((key, min(ts), max(ts), len(ts)) for key, ts in by_key.items())

